using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.JNT.JuntaDetalle;using GraphApi.Services.JNT.JuntaDetalle;namespace GraphApi.Controllers.JNT.JuntaDetalle{    /// <summary>    /// Gestión de JuntaDetalles: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("JNT/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre JuntaDetalles")]    public class JuntaDetalleController : Controller    {        private readonly IJuntaDetalleService _objService;        public JuntaDetalleController(IJuntaDetalleService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los JuntaDetalles, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="juntaDetalleID">JuntaDetalleID</param>        /// <param name="juntaID">JuntaID</param>        /// <param name="contenido">Contenido</param>        /// <param name="fechaRegistro">FechaRegistro</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de JuntaDetalles</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar JuntaDetalles",            Description = "Devuelve JuntaDetalles aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadJuntaDetalle>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadJuntaDetalle>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? juntaDetalleID,            [FromQuery] int? juntaID,            [FromQuery] string? contenido,            [FromQuery] DateTime? fechaRegistro,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetJuntaDetallesDynamic(                juntaDetalleID,                 juntaID,                 contenido,                 fechaRegistro,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo JuntaDetalle.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del JuntaDetalle a crear.</param>        /// <returns>El JuntaDetalle recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear JuntaDetalles",            Description = "Inserta un nuevo JuntaDetalle en la base de datos."        )]        [ProducesResponseType(typeof(clReadJuntaDetalle), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadJuntaDetalle>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateJuntaDetalle objInput)        {            var vCreated = await _objService.CreateJuntaDetalle(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de JuntaDetalle.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del JuntaDetalle.</param>        /// <returns>El JuntaDetalle actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar JuntaDetalles",            Description = "Actualiza uno o varios campos de JuntaDetalle existente."        )]        [ProducesResponseType(typeof(clReadJuntaDetalle), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadJuntaDetalle>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateJuntaDetalle objInput)        {            var vUpdated = await _objService.UpdateJuntaDetalle(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un JuntaDetalle por su ID.        /// </summary>        [HttpDelete("{nJuntaDetalleID:int}")]        [SwaggerOperation(            Summary = "Eliminar JuntaDetalle",            Description = "Borra un JuntaDetalle si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nJuntaDetalleID)        {            var success = await _objService.DeleteJuntaDetalle(nJuntaDetalleID);            return success ? NoContent() : NotFound();        }    }}